import java.util.*;

class Solution {
    public long dividePlayers(int[] skill) {
        long total = 0;
        for (int x : skill) total += x;
        int pairs = skill.length / 2;
        if (total % pairs != 0) return -1;
        int target = (int) (total / pairs);

        Map<Integer, Integer> count = new HashMap<>();
        for (int x : skill) {
            count.put(x, count.getOrDefault(x, 0) + 1);
        }

        long chemistry = 0;
        for (int x : skill) {
            if (count.getOrDefault(x, 0) == 0) continue;
            count.put(x, count.get(x) - 1);
            int y = target - x;
            if (count.getOrDefault(y, 0) == 0) return -1;
            count.put(y, count.get(y) - 1);
            chemistry += (long) x * y;
        }
        return chemistry;
    }
}

class Solution {
    public long dividePlayers(int[] skill) {
        long total = 0;
        int maxSkill = 0;
        for (int x : skill) {
            total += x;
            maxSkill = Math.max(maxSkill, x);
        }
        int pairs = skill.length / 2;
        if (total % pairs != 0) return -1;
        int target = (int) (total / pairs);
        if (target < 0) return -1;

        int[] count = new int[Math.max(maxSkill, target) + 1];
        for (int x : skill) count[x]++;

        long chemistry = 0;
        for (int x = 1; x < count.length; x++) {
            if (count[x] == 0) continue;
            int y = target - x;
            if (y < 0 || y >= count.length || count[y] == 0) return -1;
            if (x == y) {
                if (count[x] % 2 != 0) return -1;
                chemistry += (long) (count[x] / 2) * x * y;
                count[x] = 0;
            } else {
                if (count[x] != count[y]) return -1;
                chemistry += (long) count[x] * x * y;
                count[y] = 0;
                count[x] = 0;
            }
        }
        return chemistry;
    }
}

import java.util.*;

class Solution {
    public long dividePlayers(int[] skill) {
        TreeMap<Integer, Integer> multiset = new TreeMap<>();
        for (int x : skill) {
            multiset.put(x, multiset.getOrDefault(x, 0) + 1);
        }
        int target = multiset.firstKey() + multiset.lastKey();
        long chemistry = 0;
        while (!multiset.isEmpty()) {
            int low = multiset.firstKey();
            int high = multiset.lastKey();
            if (low + high != target) return -1;
            if (!take(multiset, low)) return -1;
            if (!take(multiset, high)) return -1;
            chemistry += (long) low * high;
        }
        return chemistry;
    }

    private boolean take(TreeMap<Integer, Integer> multiset, int value) {
        Integer count = multiset.get(value);
        if (count == null || count == 0) return false;
        if (count == 1) multiset.remove(value);
        else multiset.put(value, count - 1);
        return true;
    }
}

import java.util.*;

class Solution {
    public long dividePlayers(int[] skill) {
        long total = 0;
        Map<Integer, Integer> count = new HashMap<>();
        for (int x : skill) {
            total += x;
            count.put(x, count.getOrDefault(x, 0) + 1);
        }
        int pairs = skill.length / 2;
        if (total % pairs != 0) return -1;
        int target = (int) (total / pairs);

        Set<Integer> seen = new HashSet<>();
        long chemistry = 0;
        for (Map.Entry<Integer, Integer> entry : count.entrySet()) {
            int x = entry.getKey();
            if (seen.contains(x)) continue;
            int y = target - x;
            int countX = entry.getValue();
            int countY = count.getOrDefault(y, 0);
            if (x == y) {
                if (countX % 2 != 0) return -1;
                chemistry += (long) (countX / 2) * x * x;
            } else {
                if (countX != countY) return -1;
                chemistry += (long) countX * x * y;
            }
            seen.add(x);
            seen.add(y);
        }
        return chemistry;
    }
}
